package com.dappunq.persistence;
import jakarta.persistence.*; import java.math.*;
@Entity @Table(name="tenencias",uniqueConstraints=@UniqueConstraint(columnNames={"usuario_id","jugador_id"})) public class HoldingEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @ManyToOne(optional=false) @JoinColumn(name="usuario_id") UserEntity user; @ManyToOne(optional=false) @JoinColumn(name="jugador_id") PlayerEntity player; @Column(nullable=false) Integer tokens; @Column(name="valor_total",nullable=false,precision=15,scale=2) BigDecimal valorTotal=BigDecimal.ZERO; @Column(name="valor_unitario",nullable=false,precision=15,scale=2) BigDecimal valorUnitario=BigDecimal.ZERO; protected HoldingEntity(){} public HoldingEntity(UserEntity u,PlayerEntity p,Integer t){user=u;player=p;tokens=t;} public Long getId(){return id;} public UserEntity getUser(){return user;} public PlayerEntity getPlayer(){return player;} public Integer getTokens(){return tokens;} public BigDecimal getValorTotal(){return valorTotal;} public BigDecimal getValorUnitario(){return valorUnitario;} public void valuate(BigDecimal v){valorUnitario=v.setScale(2,RoundingMode.HALF_UP);valorTotal=valorUnitario.multiply(BigDecimal.valueOf(tokens)).setScale(2,RoundingMode.HALF_UP);} }
